package com.choco.catalog.domain.product;

import java.util.Locale;
import java.util.Set;
import java.util.UUID;

/**
 * A product photograph.
 *
 * <p>Only metadata is held here: the bytes live in object storage and are addressed by an opaque
 * {@code storageKey} the catalog service generates. Two consequences matter. First, the domain never
 * handles a file or a path, so an upload cannot influence the business model. Second, the key is
 * generated by the service, never taken from the uploaded file's name, so a caller cannot choose a
 * key that collides with or overwrites another product's image.
 *
 * <p>The content type is validated against a small allow-list of image types. That check is the first
 * line of defence against an uploaded script being served back as an image; the storage layer repeats
 * it, because a defence that exists in only one place fails when that one place is bypassed.
 */
public class ProductImage {

    /** Image types a product photograph may use. Anything else is refused. */
    public static final Set<String> ALLOWED_CONTENT_TYPES =
            Set.of("image/jpeg", "image/png", "image/webp");

    /** Hard ceiling on one image, enforced before the bytes are read. */
    public static final long MAX_BYTES = 5L * 1024 * 1024;

    private static final int MAX_ALT_TEXT = 200;

    private final UUID id;
    private final UUID productId;
    private final String storageKey;
    private String contentType;
    private long sizeBytes;
    private String altText;
    private int displayOrder;
    private boolean primaryImage;

    private ProductImage(UUID id, UUID productId, String storageKey, String contentType, long sizeBytes,
                         String altText, int displayOrder, boolean primaryImage) {
        this.id = id;
        this.productId = productId;
        this.storageKey = requireStorageKey(storageKey);
        this.contentType = requireContentType(contentType);
        this.sizeBytes = requireSize(sizeBytes);
        this.altText = normaliseAltText(altText);
        this.displayOrder = displayOrder;
        this.primaryImage = primaryImage;
    }

    public static ProductImage create(UUID id, UUID productId, String storageKey, String contentType,
                                      long sizeBytes, String altText, int displayOrder) {
        if (productId == null) {
            throw new IllegalArgumentException("Product id is required");
        }
        return new ProductImage(id, productId, storageKey, contentType, sizeBytes, altText, displayOrder,
                false);
    }

    public static ProductImage rehydrate(UUID id, UUID productId, String storageKey, String contentType,
                                         long sizeBytes, String altText, int displayOrder,
                                         boolean primaryImage) {
        return new ProductImage(id, productId, storageKey, contentType, sizeBytes, altText, displayOrder,
                primaryImage);
    }

    public void describe(String altText, int displayOrder) {
        this.altText = normaliseAltText(altText);
        this.displayOrder = displayOrder;
    }

    public void markPrimary() {
        this.primaryImage = true;
    }

    public void clearPrimary() {
        this.primaryImage = false;
    }

    /**
     * Validates an upload before a single byte is stored.
     *
     * <p>Static because it must run before an entity exists: the caller checks the declared type and
     * the declared size first, and only then streams the content. Reading an unbounded upload to
     * discover it is too large is itself the denial-of-service.
     */
    public static void assertAcceptableUpload(String contentType, long sizeBytes) {
        if (contentType == null || contentType.isBlank()) {
            throw new IllegalArgumentException("Image content type is required");
        }
        String normalised = contentType.trim().toLowerCase(Locale.ROOT);
        if (!ALLOWED_CONTENT_TYPES.contains(normalised)) {
            throw new IllegalArgumentException("Unsupported image type: " + contentType
                    + ". Allowed types are " + String.join(", ", ALLOWED_CONTENT_TYPES));
        }
        if (sizeBytes <= 0) {
            throw new IllegalArgumentException("Image is empty");
        }
        if (sizeBytes > MAX_BYTES) {
            throw new IllegalArgumentException("Image must be at most " + (MAX_BYTES / (1024 * 1024))
                    + " MB");
        }
    }

    private static String requireStorageKey(String value) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException("Image storage key is required");
        }
        return value;
    }

    private static String requireContentType(String value) {
        String normalised = value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
        if (!ALLOWED_CONTENT_TYPES.contains(normalised)) {
            throw new IllegalArgumentException("Unsupported image type: " + value);
        }
        return normalised;
    }

    private static long requireSize(long sizeBytes) {
        if (sizeBytes <= 0) {
            throw new IllegalArgumentException("Image is empty");
        }
        if (sizeBytes > MAX_BYTES) {
            throw new IllegalArgumentException("Image must be at most " + (MAX_BYTES / (1024 * 1024))
                    + " MB");
        }
        return sizeBytes;
    }

    private static String normaliseAltText(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        String trimmed = value.trim().replaceAll("\\s+", " ");
        if (trimmed.length() > MAX_ALT_TEXT) {
            throw new IllegalArgumentException("Alt text must be at most " + MAX_ALT_TEXT + " characters");
        }
        return trimmed;
    }

    public UUID id() {
        return id;
    }

    public UUID productId() {
        return productId;
    }

    public String storageKey() {
        return storageKey;
    }

    public String contentType() {
        return contentType;
    }

    public long sizeBytes() {
        return sizeBytes;
    }

    public String altText() {
        return altText;
    }

    public int displayOrder() {
        return displayOrder;
    }

    public boolean isPrimary() {
        return primaryImage;
    }
}
